// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a Complex128Array...
{
	const s = new Complex128( 1.0, 2.0 );

	znthIndexOf.ndarray( 3, 2, s, '10', 1, 0 ); // $ExpectError
	znthIndexOf.ndarray( 3, 2, s, true, 1, 0 ); // $ExpectError
	znthIndexOf.ndarray( 3, 2, s, false, 1, 0 ); // $ExpectError
	znthIndexOf.ndarray( 3, 2, s, null, 1, 0 ); // $ExpectError
	znthIndexOf.ndarray( 3, 2, s, undefined, 1, 0 ); // $ExpectError
	znthIndexOf.ndarray( 3, 2, s, {}, 1, 0 ); // $ExpectError
	znthIndexOf.ndarray( 3, 2, s, ( x: number ): number => x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fifth argument which is not a number...
{
	const x = new Complex128Array( [ 1.0, 2.0, 3.0, 4.0, 1.0, 2.0 ] );
	const s = new Complex128( 1.0, 2.0 );

	znthIndexOf.ndarray( x.length, 2, s, x, '10', 0 ); // $ExpectError
	znthIndexOf.ndarray( x.length, 2, s, x, true, 0 ); // $ExpectError
	znthIndexOf.ndarray( x.length, 2, s, x, false, 0 ); // $ExpectError
	znthIndexOf.ndarray( x.length, 2, s, x, null, 0 ); // $ExpectError
	znthIndexOf.ndarray( x.length, 2, s, x, undefined, 0 ); // $ExpectError
	znthIndexOf.ndarray( x.length, 2, s, x, [], 0 ); // $ExpectError
	znthIndexOf.ndarray( x.length, 2, s, x, {}, 0 ); // $ExpectError
	znthIndexOf.ndarray( x.length, 2, s, x, ( x: number ): number => x, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a sixth argument which is not a number...
{
	const x = new Complex128Array( [ 1.0, 2.0, 3.0, 4.0, 1.0, 2.0 ] );
	const s = new Complex128( 1.0, 2.0 );

	znthIndexOf.ndarray( x.length, 2, s, x, 1, '10' ); // $ExpectError
	znthIndexOf.ndarray( x.length, 2, s, x, 1, true ); // $ExpectError
	znthIndexOf.ndarray( x.length, 2, s, x, 1, false ); // $ExpectError
	znthIndexOf.ndarray( x.length, 2, s, x, 1, null ); // $ExpectError
	znthIndexOf.ndarray( x.length, 2, s, x, 1, undefined ); // $ExpectError
	znthIndexOf.ndarray( x.length, 2, s, x, 1, [] ); // $ExpectError
	znthIndexOf.ndarray( x.length, 2, s, x, 1, {} ); // $ExpectError
	znthIndexOf.ndarray( x.length, 2, s, x, 1, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const x = new Complex128Array( [ 1.0, 2.0, 3.0, 4.0, 1.0, 2.0 ] );
	const s = new Complex128( 1.0, 2.0 );

	znthIndexOf.ndarray(); // $ExpectError
	znthIndexOf.ndarray( x.length ); // $ExpectError
	znthIndexOf.ndarray( x.length, 2 ); // $ExpectError
	znthIndexOf.ndarray( x.length, 2, s ); // $ExpectError
	znthIndexOf.ndarray( x.length, 2, s, x ); // $ExpectError
	znthIndexOf.ndarray( x.length, 2, s, x, 1 ); // $ExpectError
	znthIndexOf.ndarray( x.length, 2, s, x, 1, 0, {} ); // $ExpectError
}
